package dev.veltraph.client.chocolate;
import java.math.BigDecimal;
import java.util.*;
/** Explicit human inspection of a serialized original intent across restart/PWC; never automatic receipt adoption. */
final class ChocolateQueueRecovery {
    static final String DECLARATION="declare-original-account";
    record Inspection(String intentId,String originalScope,String declaration,ChocolateFactoryObservation observed,int hotbar,long declaredMillis) {}
    record Plan(ChocolateQueueIntent intent,ChocolateFactoryModule.Journal pending,ChocolateFactoryModule.Journal resolved,Inspection inspection,ChocolateFactoryRuntime.ManualClosureSnapshot runtimeBefore,BigDecimal knownSpent,BigDecimal manualDebit) {}
    static Inspection inspect(ChocolateQueueIntent intent,String id,String scope,String declaration,ChocolateFactoryObservation observed,int hotbar,long now){
        if(intent==null||!intent.id().equals(id)||!intent.scope().equals(scope)||!DECLARATION.equals(declaration))throw new IllegalArgumentException("Exact retained intent ID, original scope and deliberate original-account declaration required; identity remains unproven");
        var profile=ChocolateFactoryProfile.decode(intent.profileJson());if(observed==null||!observed.scope().equals(scope)||!observed.title().equals(intent.title())||!observed.profileVerified()||!observed.contextBound()||!observed.cursorEmpty()||!observed.fresh(now,profile.freshnessMillis())||hotbar!=intent.selectedHotbar()||!ChocolateQueueIntent.protectedRows(observed).equals(intent.protectedFingerprints())||observed.balance().isEmpty()||observed.production().isEmpty()||observed.capacity().isEmpty())throw new IllegalArgumentException("Fresh complete original-profile native inspection, cursor, hotbar and protected inventory/equipment required");
        var target=observed.targets().get(intent.upgrade());if(target==null||target.kind()!=intent.kind()||target.slot()!=intent.slot())throw new IllegalArgumentException("Original target is not present in inspected native menu");
        return new Inspection(id,scope,declaration,observed,hotbar,now);
    }
    static Plan prepare(ChocolateQueueIntent intent,ChocolateFactoryModule.Journal pending,Inspection declared,boolean purchased,ChocolateFactoryRuntime runtime,long now){
        if(pending==null||pending.schema()!=1||!Set.of("PENDING","UNKNOWN","ACKNOWLEDGED_UNPERSISTED").contains(pending.status())||!pending.intentId().equals(intent.id())||!pending.scope().equals(intent.scope())||!pending.upgrade().equals(intent.upgrade())||new BigDecimal(pending.price()).compareTo(new BigDecimal(intent.price()))!=0||declared==null)throw new IllegalArgumentException("Original unresolved journal and serialized intent must agree");
        var checked=inspect(intent,declared.intentId(),declared.originalScope(),declared.declaration(),declared.observed(),declared.hotbar(),now);var before=runtime.manualClosureSnapshot();boolean restarted=before.state()==ChocolateFactoryRuntime.State.IDLE&&before.selection()==null&&before.intentId().isBlank()&&before.spent().signum()==0&&before.manual().signum()==0&&before.acknowledgments().isEmpty();boolean abandonedBeforeDispatch=before.state()==ChocolateFactoryRuntime.State.IDLE&&before.selection()==null&&before.intentId().equals(intent.id())&&"PENDING".equals(pending.status())&&runtime.requestSentAtMillis()==0;boolean retained=before.selection()!=null&&before.selection().intentId().equals(intent.id())&&before.intentId().equals(intent.id())&&(before.state()==ChocolateFactoryRuntime.State.UNKNOWN||before.state()==ChocolateFactoryRuntime.State.ACKNOWLEDGED);
        if(!restarted&&!retained&&!abandonedBeforeDispatch)throw new IllegalArgumentException("Different live runtime intent cannot be adopted or overwritten");
        boolean knownAck="ACKNOWLEDGED_UNPERSISTED".equals(pending.status());var price=new BigDecimal(intent.price());var known=new BigDecimal(pending.spent());var manual=new BigDecimal(pending.manualDeclaredDebit());var expectedKnown=new BigDecimal(intent.knownSpentBefore()).add(knownAck?price:BigDecimal.ZERO);
        if(known.compareTo(expectedKnown)!=0||manual.compareTo(new BigDecimal(intent.manualDebitBefore()))!=0||(retained||abandonedBeforeDispatch)&&(before.spent().compareTo(known)!=0||before.manual().compareTo(manual)!=0)||knownAck&&!purchased)throw new IllegalArgumentException("Original known spend/manual ledger conflicts with declaration");
        var o=checked.observed();var target=o.targets().get(intent.upgrade());var balance=o.balance().orElseThrow();var capacity=o.capacity().orElseThrow();var production=o.production().orElseThrow();if(now<intent.capturedMillis()||capacity.signum()<=0||production.signum()<0||balance.signum()<0||balance.compareTo(capacity)>0)throw new IllegalArgumentException("Unknown or inconsistent inspected currency/time");
        var lower=new BigDecimal(intent.beforeBalance()).subtract(purchased?price:BigDecimal.ZERO);var possibleIncome=new BigDecimal(intent.beforeProduction()).max(production).multiply(BigDecimal.valueOf(now-intent.capturedMillis())).divide(BigDecimal.valueOf(1000));var upper=lower.add(possibleIncome).min(capacity);if(balance.compareTo(lower)<0||balance.compareTo(upper)>0||balance.compareTo(new BigDecimal(intent.reserve()))<0)throw new IllegalArgumentException("Observed wallet contradicts declared original debit/reserve; no guessed future recharge/price adopted");
        if(purchased){if(target.level()!=intent.level()+1||ChocolateQueueIntent.fingerprint(target.fullIdentity()).equals(intent.targetFingerprint()))throw new IllegalArgumentException("Purchased manual declaration requires observed exact level+1 and changed full target identity");}else{var quote=o.quotes().get(intent.upgrade());if(target.level()!=intent.level()||!ChocolateQueueIntent.fingerprint(target.fullIdentity()).equals(intent.targetFingerprint())||quote==null||quote.price().compareTo(price)!=0)throw new IllegalArgumentException("Not-purchased declaration requires unchanged exact target and quote");}
        var nextManual=manual.add(purchased&&!knownAck?price:BigDecimal.ZERO);if(known.add(nextManual).compareTo(new BigDecimal(intent.budget()))>0)throw new IllegalArgumentException("Manual debit exceeds retained run budget");
        var reason="Explicit human original-account inspection declaration; account identity UNPROVEN; original intent="+intent.id()+"; original scope="+intent.scope()+"; result="+(purchased?"purchased":"not-purchased")+"; inspection revision="+o.revision()+", time="+o.observedMillis()+", level="+target.level()+", wallet="+balance+"; original acquisition="+intent.capturedMillis()+"; "+intent.accountBoundary()+"; native known spend="+known+"; separate manual Chocolate debit="+nextManual+"; Coin valuation UNKNOWN; no native ACK/financial UUID manufactured; fresh deliberate selection required";
        var resolved=new ChocolateFactoryModule.Journal(1,intent.scope(),ChocolateFactoryProfile.decode(intent.profileJson()).verifiedOn(),"RECONCILED",intent.upgrade(),intent.price(),known.toPlainString(),reason,nextManual.toPlainString(),intent.id());return new Plan(intent,pending,resolved,checked,before,known,nextManual);
    }
    static boolean matchesInspection(ChocolateQueueIntent intent,Inspection bound,ChocolateFactoryObservation current,int hotbar,long now){return bound!=null&&current!=null&&current.fresh(now,ChocolateFactoryProfile.decode(intent.profileJson()).freshnessMillis())&&hotbar==bound.hotbar()&&ChocolateQueueManualReconciliation.sameInspection(bound.observed(),current);}
    static boolean unchangedRuntime(ChocolateFactoryRuntime runtime,Plan plan){return runtime.manualClosureSnapshot().equals(plan.runtimeBefore());}
}
